```python
def transform(grid):
    if not grid or not grid[0]:
        return grid

    rows = len(grid)
    cols = len(grid[0])

    # Find pattern column (most unique values)
    pattern_col = 0
    max_unique = 0
    for c in range(cols):
        unique_count = len(set(grid[r][c] for r in range(rows)))
        if unique_count > max_unique:
            max_unique = unique_count
            pattern_col = c

    # Get sorted unique values from pattern column
    pattern_values = sorted(set(grid[r][pattern_col] for r in range(rows)))
    pattern_len = len(pattern_values)

    # Find threshold: first column with unique count < pattern length
    threshold = cols
    for c in range(cols):
        if len(set(grid[r][c] for r in range(rows))) < pattern_len:
            threshold = c
            break

    # Build result grid
    result = [[0] * cols for _ in range(rows)]
    for r in range(rows):
        for c in range(cols):
            if c < threshold:
                result[r][c] = grid[r][c]
            else:
                val = pattern_values[c % pattern_len]
                if val not in (grid[r][i] for i in range(cols)):
                    result[r][c] = val
                else:
                    result[r][c] = grid[r][c]

    return result
